using System;
using LittleLeo;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OnStartOfTurnOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/OnStartOfTurn Omen Data")]
public class OnStartOfTurnOmenData : OmenData
{
	[Header("OnStartOfTurn Omen")]
	[SerializeField]
	private bool resetBetweenBattles;

	[SerializeField]
	private bool beforeLightShieldRemoval;

	private Action omenAction;

	private Action omenCheckActivationAction;

	protected OmenInstance omenInstance;

	public override void Initialize(OmenInstance omenInstance)
	{
		counter = 0;
		omenAction = (EnableOmenCounter ? OmenWithCounterAction(omenInstance) : OmenNoCounterAction(omenInstance));
		if (EnableOmenCounter)
		{
			omenCheckActivationAction = delegate
			{
				if (OmenAboutToTrigger())
				{
					if (beforeLightShieldRemoval)
					{
						ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfTurnOmenBeforeLightShieldRemovalOmenActions.Add(omenAction);
					}
					else
					{
						ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfTurnOmenActions.Add(omenAction);
					}
				}
				else
				{
					ActivateOmen();
					if (!base.DifficultyLevelOmenData)
					{
						omenInstance.UpdateOmenCounter();
						if (OmenAboutToTrigger())
						{
							omenInstance.PlayBlinkingFeedback();
						}
					}
				}
			};
		}
		else
		{
			omenCheckActivationAction = delegate
			{
				if (beforeLightShieldRemoval)
				{
					ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfTurnOmenBeforeLightShieldRemovalOmenActions.Add(omenAction);
				}
				else
				{
					ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfTurnOmenActions.Add(omenAction);
				}
			};
		}
		if (beforeLightShieldRemoval)
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfTurnOmenBeforeLightShieldRemovalCheckActivateActions.Add(omenCheckActivationAction);
		}
		else
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfTurnOmenCheckActivateActions.Add(omenCheckActivationAction);
		}
		if (resetBetweenBattles)
		{
			if (!base.DifficultyLevelOmenData)
			{
				ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Add(omenInstance);
				this.omenInstance = omenInstance;
			}
			else
			{
				ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmensDifficultyLevel.Add(this);
			}
		}
	}

	private bool OmenAboutToTrigger()
	{
		return counter == TriggerAmount - 1;
	}

	private Action OmenWithCounterAction(OmenInstance omenInstance)
	{
		return delegate
		{
			if (OmenAboutToTrigger() && !base.DifficultyLevelOmenData)
			{
				omenInstance.ActivateOmenFeedback();
				omenInstance.StopBlinkingFeedback();
			}
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.6f, delegate
			{
				ActivateOmen();
				if (!base.DifficultyLevelOmenData)
				{
					omenInstance.UpdateOmenCounter();
				}
			});
		};
	}

	private Action OmenNoCounterAction(OmenInstance omenInstance)
	{
		return delegate
		{
			if (!base.DifficultyLevelOmenData)
			{
				omenInstance.ActivateOmenFeedback();
			}
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.6f, delegate
			{
				ActivateOmen();
			});
		};
	}

	public override void OmenRemoved()
	{
		if (beforeLightShieldRemoval)
		{
			if (ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfTurnOmenBeforeLightShieldRemovalCheckActivateActions.Contains(omenCheckActivationAction))
			{
				ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfTurnOmenBeforeLightShieldRemovalCheckActivateActions.Remove(omenCheckActivationAction);
			}
		}
		else if (ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfTurnOmenCheckActivateActions.Contains(omenCheckActivationAction))
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfTurnOmenCheckActivateActions.Remove(omenCheckActivationAction);
		}
		if (resetBetweenBattles)
		{
			if (!base.DifficultyLevelOmenData)
			{
				ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Remove(omenInstance);
				omenInstance = null;
			}
			else
			{
				ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmensDifficultyLevel.Remove(this);
			}
		}
	}

	public override string OmenConvertedDescription()
	{
		string text = (EnableOmenCounter ? base.localizationManager.GetLocalizedEveryXTurns() : base.localizationManager.GetLocalizedAtTheStartOfYourTurn());
		if (EnableOmenCounter)
		{
			text = Smart.Format(text, TriggerAmount);
		}
		string text2 = base.OmenConvertedDescription();
		return text + base.localizationManager.GetLocalizedSpace() + text2;
	}
}
